I’ll make this as a true one-file page: editable hunt details, kid-friendly clue cards, checklist generation, print styling, and no external libraries. It will avoid pretending to know exact sky conditions, using your “sky note” field to personalize the printout.

Save this as stargazing-scavenger-hunt.html and open it in a browser. It is fully self-contained and print-ready. 🌙

HTML
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Backyard Stargazing Scavenger Hunt</title>
  <style>
    :root {
      --bg: #07111f;
      --panel: #101d31;
      --panel2: #16263f;
      --ink: #f5f7fb;
      --muted: #aebbd1;
      --line: rgba(255,255,255,.14);
      --accent: #ffd166;
      --accent2: #7dd3fc;
      --good: #9ef01a;
      --paper: #ffffff;
      --paperInk: #182033;
      --shadow: 0 20px 60px rgba(0,0,0,.35);
      --radius: 22px;
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      font-family: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at 18% 8%, rgba(125, 211, 252, .18), transparent 28%),
        radial-gradient(circle at 82% 16%, rgba(255, 209, 102, .15), transparent 26%),
        linear-gradient(145deg, #040912, var(--bg) 45%, #0d1b2f);
      color: var(--ink);
      min-height: 100vh;
    }

    .stars {
      position: fixed;
      inset: 0;
      pointer-events: none;
      opacity: .55;
      background-image:
        radial-gradient(circle, rgba(255,255,255,.8) 1px, transparent 1.6px),
        radial-gradient(circle, rgba(255,255,255,.55) 1px, transparent 1.6px),
        radial-gradient(circle, rgba(255,255,255,.35) 1px, transparent 1.6px);
      background-size: 90px 90px, 140px 140px, 210px 210px;
      background-position: 10px 20px, 50px 80px, 120px 20px;
    }

    .app {
      position: relative;
      width: min(1180px, calc(100% - 32px));
      margin: 0 auto;
      padding: 36px 0 56px;
    }

    header {
      display: grid;
      grid-template-columns: 1fr auto;
      gap: 20px;
      align-items: start;
      margin-bottom: 22px;
    }

    h1 {
      margin: 0;
      font-size: clamp(2rem, 5vw, 4.6rem);
      line-height: .95;
      letter-spacing: -0.06em;
    }

    .subtitle {
      margin: 14px 0 0;
      max-width: 780px;
      color: var(--muted);
      font-size: 1.05rem;
      line-height: 1.55;
    }

    .moon-badge {
      border: 1px solid var(--line);
      background: rgba(255,255,255,.06);
      border-radius: 999px;
      padding: 12px 16px;
      color: var(--accent);
      font-weight: 800;
      white-space: nowrap;
      box-shadow: var(--shadow);
    }

    .layout {
      display: grid;
      grid-template-columns: 380px 1fr;
      gap: 20px;
      align-items: start;
    }

    .panel {
      background: linear-gradient(180deg, rgba(255,255,255,.08), rgba(255,255,255,.04));
      border: 1px solid var(--line);
      border-radius: var(--radius);
      box-shadow: var(--shadow);
      overflow: hidden;
      backdrop-filter: blur(12px);
    }

    .panel-inner {
      padding: 20px;
    }

    .panel-title {
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 12px;
      margin-bottom: 16px;
    }

    .panel-title h2 {
      margin: 0;
      font-size: 1.05rem;
      letter-spacing: -0.02em;
    }

    .chip {
      font-size: .78rem;
      font-weight: 800;
      color: #07111f;
      background: var(--accent);
      border-radius: 999px;
      padding: 6px 10px;
    }

    label {
      display: block;
      margin: 14px 0 7px;
      color: var(--muted);
      font-size: .88rem;
      font-weight: 700;
    }

    input,
    textarea,
    select {
      width: 100%;
      border: 1px solid rgba(255,255,255,.16);
      background: rgba(5, 13, 25, .7);
      color: var(--ink);
      border-radius: 14px;
      padding: 12px 13px;
      font: inherit;
      outline: none;
    }

    textarea {
      min-height: 94px;
      resize: vertical;
    }

    input:focus,
    textarea:focus,
    select:focus {
      border-color: rgba(125, 211, 252, .75);
      box-shadow: 0 0 0 4px rgba(125, 211, 252, .13);
    }

    .row {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 12px;
    }

    .actions {
      display: grid;
      gap: 10px;
      margin-top: 18px;
    }

    button {
      border: 0;
      cursor: pointer;
      border-radius: 16px;
      padding: 13px 15px;
      font: inherit;
      font-weight: 900;
      color: #07111f;
      background: var(--accent);
      box-shadow: 0 10px 24px rgba(0,0,0,.24);
    }

    button.secondary {
      background: rgba(255,255,255,.1);
      color: var(--ink);
      border: 1px solid var(--line);
    }

    button.small {
      padding: 9px 10px;
      border-radius: 12px;
      font-size: .86rem;
    }

    button:hover {
      filter: brightness(1.04);
      transform: translateY(-1px);
    }

    .hint {
      color: var(--muted);
      font-size: .85rem;
      line-height: 1.45;
      margin-top: 12px;
    }

    .custom-add {
      display: grid;
      grid-template-columns: 1fr auto;
      gap: 8px;
      margin-top: 8px;
    }

    .preview {
      display: grid;
      gap: 20px;
    }

    .print-sheet {
      background: rgba(255,255,255,.05);
      border: 1px solid var(--line);
      border-radius: var(--radius);
      overflow: hidden;
    }

    .sheet-head {
      padding: 22px;
      display: grid;
      grid-template-columns: 1fr auto;
      gap: 14px;
      align-items: start;
      border-bottom: 1px solid var(--line);
      background:
        radial-gradient(circle at 10% 20%, rgba(255, 209, 102, .16), transparent 25%),
        linear-gradient(135deg, rgba(255,255,255,.08), rgba(255,255,255,.03));
    }

    .sheet-head h2 {
      margin: 0;
      font-size: clamp(1.4rem, 3vw, 2.1rem);
      letter-spacing: -0.04em;
    }

    .sheet-meta {
      margin-top: 8px;
      color: var(--muted);
      display: grid;
      gap: 4px;
      font-size: .95rem;
    }

    .night-note {
      border: 1px dashed rgba(255,255,255,.25);
      border-radius: 16px;
      padding: 12px;
      color: var(--muted);
      max-width: 360px;
      font-size: .92rem;
      line-height: 1.4;
    }

    .cards {
      padding: 20px;
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 14px;
    }

    .card {
      min-height: 175px;
      border: 1px solid rgba(255,255,255,.16);
      border-radius: 20px;
      padding: 17px;
      background: linear-gradient(180deg, rgba(255,255,255,.09), rgba(255,255,255,.035));
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      page-break-inside: avoid;
      break-inside: avoid;
    }

    .card-top {
      display: flex;
      align-items: start;
      justify-content: space-between;
      gap: 12px;
    }

    .card h3 {
      margin: 0;
      font-size: 1.14rem;
      letter-spacing: -0.03em;
    }

    .emoji {
      width: 44px;
      height: 44px;
      display: grid;
      place-items: center;
      background: rgba(255,255,255,.1);
      border-radius: 14px;
      font-size: 1.55rem;
      flex: 0 0 auto;
    }

    .clue {
      margin: 12px 0 0;
      color: var(--muted);
      line-height: 1.42;
      font-size: .95rem;
    }

    .find-line {
      margin-top: 14px;
      border-top: 1px solid rgba(255,255,255,.13);
      padding-top: 11px;
      color: var(--accent2);
      font-size: .9rem;
      font-weight: 800;
    }

    .checklist-wrap {
      padding: 0 20px 20px;
    }

    .checklist {
      background: rgba(255,255,255,.06);
      border: 1px solid var(--line);
      border-radius: 20px;
      padding: 18px;
    }

    .checklist h3 {
      margin: 0 0 12px;
      letter-spacing: -0.03em;
    }

    .check-grid {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 8px 14px;
    }

    .check-item {
      display: grid;
      grid-template-columns: 24px 1fr;
      gap: 9px;
      align-items: start;
      color: var(--ink);
      line-height: 1.3;
    }

    .box {
      width: 20px;
      height: 20px;
      border: 2px solid rgba(255,255,255,.65);
      border-radius: 5px;
      margin-top: 1px;
    }

    .parent-notes {
      margin-top: 14px;
      color: var(--muted);
      font-size: .9rem;
      line-height: 1.45;
    }

    .empty-state {
      color: var(--muted);
      padding: 30px;
      text-align: center;
      line-height: 1.5;
    }

    .library {
      margin-top: 14px;
      display: grid;
      gap: 8px;
    }

    .library-row {
      display: grid;
      grid-template-columns: auto 1fr;
      gap: 9px;
      align-items: start;
      color: var(--muted);
      font-size: .92rem;
      line-height: 1.35;
    }

    .library-row input {
      width: 18px;
      height: 18px;
      margin-top: 1px;
      accent-color: var(--accent);
    }

    @media (max-width: 900px) {
      header {
        grid-template-columns: 1fr;
      }

      .moon-badge {
        width: fit-content;
      }

      .layout {
        grid-template-columns: 1fr;
      }

      .cards {
        grid-template-columns: 1fr;
      }

      .sheet-head {
        grid-template-columns: 1fr;
      }

      .night-note {
        max-width: none;
      }
    }

    @media (max-width: 560px) {
      .app {
        width: min(100% - 20px, 1180px);
        padding-top: 22px;
      }

      .row,
      .check-grid {
        grid-template-columns: 1fr;
      }

      .panel-inner,
      .cards,
      .sheet-head,
      .checklist-wrap {
        padding: 16px;
      }
    }

    @media print {
      :root {
        --ink: #111827;
        --muted: #374151;
        --line: #d1d5db;
        --accent: #111827;
        --accent2: #111827;
      }

      body {
        background: #fff;
        color: #111827;
      }

      .stars,
      header,
      .controls,
      .hint,
      .no-print {
        display: none !important;
      }

      .app {
        width: 100%;
        padding: 0;
        margin: 0;
      }

      .layout {
        display: block;
      }

      .preview,
      .print-sheet {
        display: block;
      }

      .print-sheet {
        border: 0;
        border-radius: 0;
        background: #fff;
        overflow: visible;
      }

      .sheet-head {
        background: #fff;
        color: #111827;
        border: 2px solid #111827;
        border-radius: 12px;
        margin-bottom: 14px;
        padding: 16px;
      }

      .sheet-head h2 {
        font-size: 28px;
      }

      .sheet-meta,
      .night-note,
      .clue,
      .parent-notes {
        color: #374151;
      }

      .night-note {
        border-color: #9ca3af;
      }

      .cards {
        display: grid;
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
        padding: 0;
      }

      .card {
        background: #fff;
        color: #111827;
        border: 2px solid #111827;
        border-radius: 12px;
        min-height: 150px;
        padding: 13px;
      }

      .emoji {
        background: #f3f4f6;
        border: 1px solid #d1d5db;
      }

      .find-line {
        border-color: #d1d5db;
        color: #111827;
      }

      .checklist-wrap {
        padding: 14px 0 0;
      }

      .checklist {
        background: #fff;
        border: 2px solid #111827;
        border-radius: 12px;
      }

      .check-grid {
        grid-template-columns: repeat(2, 1fr);
      }

      .box {
        border-color: #111827;
      }

      @page {
        margin: .45in;
      }
    }
  </style>
</head>
<body>
  <div class="stars"></div>

  <main class="app">
    <header>
      <div>
        <h1>Backyard Stargazing Scavenger Hunt</h1>
        <p class="subtitle">
          Enter tonight’s details, choose what kids should search for, then print clue cards and a checklist. Built for quick backyard use, cloudy sky notes, flashlights, blankets, and a little moon magic.
        </p>
      </div>
      <div class="moon-badge">🌙 Print ready</div>
    </header>

    <section class="layout">
      <aside class="panel controls">
        <div class="panel-inner">
          <div class="panel-title">
            <h2>Hunt setup</h2>
            <span class="chip">One file</span>
          </div>

          <label for="huntTitle">Hunt name</label>
          <input id="huntTitle" value="Tonight’s Backyard Sky Quest" />

          <div class="row">
            <div>
              <label for="huntDate">Date</label>
              <input id="huntDate" type="date" />
            </div>
            <div>
              <label for="difficulty">Kid level</label>
              <select id="difficulty">
                <option value="little">Little explorers</option>
                <option value="mixed" selected>Mixed ages</option>
                <option value="older">Older kids</option>
              </select>
            </div>
          </div>

          <label for="skyNote">Rough location or sky note</label>
          <textarea id="skyNote">Backyard. Look away from porch lights. Trees block part of the western sky.</textarea>

          <label for="leaderNote">Leader note for the printout</label>
          <textarea id="leaderNote">Use red or dim flashlights if you have them. Let your eyes adjust for 10 minutes. Not every clue needs to be visible tonight.</textarea>

          <label>Choose clue cards</label>
          <div class="library" id="library"></div>

          <label for="customItem">Add a custom thing to find</label>
          <div class="custom-add">
            <input id="customItem" placeholder="Example: airplane blinking lights" />
            <button class="small secondary" id="addCustom" type="button">Add</button>
          </div>

          <div class="actions">
            <button id="buildBtn" type="button">Build printable hunt</button>
            <button class="secondary" id="printBtn" type="button">Print cards and checklist</button>
            <button class="secondary" id="resetBtn" type="button">Reset</button>
          </div>

          <p class="hint">
            This page does not calculate exact astronomy positions. It gives kid-friendly clues that work with your date and sky note, so you can quickly adapt to clouds, trees, city lights, or whatever is actually visible.
          </p>
        </div>
      </aside>

      <section class="preview">
        <div class="print-sheet" id="printSheet">
          <div class="sheet-head">
            <div>
              <h2 id="outTitle">Tonight’s Backyard Sky Quest</h2>
              <div class="sheet-meta">
                <div><strong>Date:</strong> <span id="outDate">Tonight</span></div>
                <div><strong>Sky note:</strong> <span id="outSky">Backyard. Look away from porch lights.</span></div>
              </div>
            </div>
            <div class="night-note">
              <strong>Leader note:</strong>
              <div id="outLeader">Use red or dim flashlights if you have them. Let your eyes adjust for 10 minutes.</div>
            </div>
          </div>

          <div class="cards" id="cards"></div>

          <div class="checklist-wrap">
            <div class="checklist">
              <h3>Finder checklist</h3>
              <div class="check-grid" id="checklist"></div>
              <div class="parent-notes">
                <strong>Bonus challenge:</strong> Pick your favorite find and draw it on the back of a clue card. Add one sentence about where you saw it in the sky.
              </div>
            </div>
          </div>
        </div>
      </section>
    </section>
  </main>

  <script>
    const clueBank = [
      {
        id: "moon",
        emoji: "🌙",
        title: "The Moon",
        checklist: "Moon",
        clue: {
          little: "Find the biggest glowing shape in the sky. Is it round, skinny, half, or missing tonight?",
          mixed: "Look for the Moon. Notice its shape, color, and whether it is bright enough to make shadows.",
          older: "Find the Moon if it is up. Sketch its phase and note whether the bright side points east, west, up, or down."
        },
        find: "Draw its shape."
      },
      {
        id: "bright",
        emoji: "✨",
        title: "Brightest Point",
        checklist: "Brightest star or planet",
        clue: {
          little: "Find the brightest tiny light that is not the Moon. Does it twinkle or shine steady?",
          mixed: "Find the brightest point of light. Stars usually twinkle. Planets often shine more steadily.",
          older: "Compare the brightest point with nearby stars. Record whether it twinkles strongly or looks steady."
        },
        find: "Circle twinkle or steady."
      },
      {
        id: "dipper",
        emoji: "🥄",
        title: "Big Dipper Shape",
        checklist: "Big Dipper or spoon shape",
        clue: {
          little: "Look for stars shaped like a giant spoon or wagon. Count how many stars you can see.",
          mixed: "Try to find a spoon shape in the northern sky. It may be high, low, tilted, or partly hidden.",
          older: "Find the Big Dipper if visible. Use the two stars at the outer bowl edge as pointer stars toward north."
        },
        find: "Count the stars in the shape."
      },
      {
        id: "north",
        emoji: "🧭",
        title: "North Star",
        checklist: "North Star",
        clue: {
          little: "Find the star that seems like the sky turns around it. A grownup can help point north.",
          mixed: "Use a compass or phone compass to face north. Look for a medium bright star that stays in nearly the same place.",
          older: "Use the Big Dipper pointer stars to estimate Polaris, the North Star, then mark north on your checklist."
        },
        find: "Write which way north is."
      },
      {
        id: "triangle",
        emoji: "🔺",
        title: "Summer Triangle",
        checklist: "Three bright stars making a triangle",
        clue: {
          little: "Try to find three bright stars that make a huge triangle.",
          mixed: "Look for three bright stars spread far apart. Together they can make a big summer sky triangle.",
          older: "Find three bright stars forming a large triangle. Estimate which corner is highest above the horizon."
        },
        find: "Draw the triangle."
      },
      {
        id: "colors",
        emoji: "🎨",
        title: "Star Colors",
        checklist: "Two stars with different colors",
        clue: {
          little: "Find one star that looks white or blue and one that looks yellow or orange.",
          mixed: "Compare stars carefully. Some look icy white, some blue white, some yellow, and some orange.",
          older: "Find two stars with different color temperatures. Record the colors without using a phone screen."
        },
        find: "Write two colors."
      },
      {
        id: "satellite",
        emoji: "🛰️",
        title: "Silent Mover",
        checklist: "Satellite or slow moving light",
        clue: {
          little: "Watch for a tiny light moving smoothly across the sky with no blinking.",
          mixed: "A satellite looks like a steady dot sliding across the sky. It usually does not blink like a plane.",
          older: "Track a steady moving dot. Estimate its path from horizon to horizon and how long you watched it."
        },
        find: "Point where it started."
      },
      {
        id: "plane",
        emoji: "✈️",
        title: "Blinking Plane",
        checklist: "Blinking airplane",
        clue: {
          little: "Find a light that blinks red, green, or white. That is probably an airplane.",
          mixed: "Find a blinking moving light. Compare it with a satellite, which usually looks steady.",
          older: "Watch a blinking aircraft and note its direction. Compare its speed with any steady moving object."
        },
        find: "Write blink colors."
      },
      {
        id: "cloud",
        emoji: "☁️",
        title: "Cloud Window",
        checklist: "A clear patch between clouds",
        clue: {
          little: "Find a hole in the clouds where stars peek through.",
          mixed: "Look for a clear window between clouds. Watch whether it grows, shrinks, or moves.",
          older: "Track a cloud gap for two minutes. Estimate which direction the clouds are drifting."
        },
        find: "Draw the cloud gap."
      },
      {
        id: "milky",
        emoji: "🌌",
        title: "Faint Glow Hunt",
        checklist: "Faint glow or crowded star patch",
        clue: {
          little: "Look for a soft cloudy glow made of many tiny stars. It is hard to see near city lights.",
          mixed: "Find the faintest patch of sky you can. It might be a crowded star area, thin cloud, or sky glow.",
          older: "Search the darkest part of the sky for a faint band or dense star region. Note how light pollution affects it."
        },
        find: "Mark easy or hard."
      },
      {
        id: "shadow",
        emoji: "👤",
        title: "Moon Shadow",
        checklist: "Shadow made by moonlight",
        clue: {
          little: "If the Moon is bright, stand still and look for your moon shadow.",
          mixed: "Try to make a shadow using only moonlight. This works best when the Moon is bright and high.",
          older: "Test whether the Moon casts a visible shadow. Record what object made the clearest shadow."
        },
        find: "Write yes or no."
      },
      {
        id: "quiet",
        emoji: "👂",
        title: "Night Sound",
        checklist: "One nighttime sound",
        clue: {
          little: "Close your eyes for ten seconds. What night sound can you hear?",
          mixed: "Take a quiet listening break. Find one sound from nature and one sound from people or cars.",
          older: "Listen for 30 seconds and separate sounds into nature, people, traffic, and weather."
        },
        find: "Write one sound."
      }
    ];

    let selectedIds = ["moon", "bright", "dipper", "north", "triangle", "colors", "satellite", "plane"];
    let customClues = [];

    const $ = (id) => document.getElementById(id);

    function todayForInput() {
      const now = new Date();
      const offset = now.getTimezoneOffset();
      const local = new Date(now.getTime() - offset * 60000);
      return local.toISOString().slice(0, 10);
    }

    function prettyDate(value) {
      if (!value) return "Tonight";
      const date = new Date(value + "T12:00:00");
      return date.toLocaleDateString(undefined, {
        weekday: "long",
        month: "long",
        day: "numeric",
        year: "numeric"
      });
    }

    function escapeHTML(str) {
      return String(str)
        .replaceAll("&", "&amp;")
        .replaceAll("<", "&lt;")
        .replaceAll(">", "&gt;")
        .replaceAll('"', "&quot;")
        .replaceAll("'", "&#039;");
    }

    function getDifficulty() {
      return $("difficulty").value || "mixed";
    }

    function allClues() {
      return [
        ...clueBank,
        ...customClues.map((name, index) => ({
          id: "custom-" + index + "-" + name.toLowerCase().replace(/[^a-z0-9]+/g, ""),
          emoji: "⭐",
          title: name,
          checklist: name,
          clue: {
            little: "Find this special item: " + name + ". Ask a grownup for a hint if you need one.",
            mixed: "Find this custom sky item: " + name + ". Record where you saw it.",
            older: "Find this custom target: " + name + ". Note its direction and what helped you identify it."
          },
          find: "Write where you found it.",
          custom: true
        }))
      ];
    }

    function renderLibrary() {
      const library = $("library");
      library.innerHTML = "";

      clueBank.forEach(item => {
        const row = document.createElement("label");
        row.className = "library-row";
        row.innerHTML = `
          <input type="checkbox" value="${item.id}" ${selectedIds.includes(item.id) ? "checked" : ""}>
          <span><strong>${item.emoji} ${escapeHTML(item.title)}</strong><br>${escapeHTML(item.checklist)}</span>
        `;
        library.appendChild(row);
      });

      library.querySelectorAll("input[type='checkbox']").forEach(box => {
        box.addEventListener("change", () => {
          selectedIds = Array.from(library.querySelectorAll("input[type='checkbox']:checked")).map(input => input.value);
          saveState();
          buildHunt();
        });
      });
    }

    function buildHunt() {
      const difficulty = getDifficulty();
      const title = $("huntTitle").value.trim() || "Tonight’s Backyard Sky Quest";
      const date = prettyDate($("huntDate").value);
      const sky = $("skyNote").value.trim() || "Backyard sky check.";
      const leader = $("leaderNote").value.trim() || "Let your eyes adjust and only search for what is visible tonight.";

      $("outTitle").textContent = title;
      $("outDate").textContent = date;
      $("outSky").textContent = sky;
      $("outLeader").textContent = leader;

      const chosen = allClues().filter(item => selectedIds.includes(item.id) || item.custom);
      const cards = $("cards");
      const checklist = $("checklist");

      cards.innerHTML = "";
      checklist.innerHTML = "";

      if (!chosen.length) {
        cards.innerHTML = `<div class="empty-state">Pick at least one clue card to build the hunt.</div>`;
        return;
      }

      chosen.forEach((item, idx) => {
        const card = document.createElement("article");
        card.className = "card";
        card.innerHTML = `
          <div>
            <div class="card-top">
              <h3>${idx + 1}. ${escapeHTML(item.title)}</h3>
              <div class="emoji">${item.emoji}</div>
            </div>
            <p class="clue">${escapeHTML(item.clue[difficulty] || item.clue.mixed)}</p>
          </div>
          <div class="find-line">${escapeHTML(item.find)}</div>
        `;
        cards.appendChild(card);

        const check = document.createElement("div");
        check.className = "check-item";
        check.innerHTML = `
          <span class="box"></span>
          <span>${escapeHTML(item.checklist)}</span>
        `;
        checklist.appendChild(check);
      });

      saveState();
    }

    function saveState() {
      const state = {
        huntTitle: $("huntTitle").value,
        huntDate: $("huntDate").value,
        skyNote: $("skyNote").value,
        leaderNote: $("leaderNote").value,
        difficulty: $("difficulty").value,
        selectedIds,
        customClues
      };
      localStorage.setItem("stargazing-hunt-state", JSON.stringify(state));
    }

    function loadState() {
      const raw = localStorage.getItem("stargazing-hunt-state");
      if (!raw) {
        $("huntDate").value = todayForInput();
        return;
      }

      try {
        const state = JSON.parse(raw);
        $("huntTitle").value = state.huntTitle || "Tonight’s Backyard Sky Quest";
        $("huntDate").value = state.huntDate || todayForInput();
        $("skyNote").value = state.skyNote || "";
        $("leaderNote").value = state.leaderNote || "";
        $("difficulty").value = state.difficulty || "mixed";
        selectedIds = Array.isArray(state.selectedIds) ? state.selectedIds : selectedIds;
        customClues = Array.isArray(state.customClues) ? state.customClues : [];
      } catch {
        $("huntDate").value = todayForInput();
      }
    }

    function resetHunt() {
      localStorage.removeItem("stargazing-hunt-state");
      selectedIds = ["moon", "bright", "dipper", "north", "triangle", "colors", "satellite", "plane"];
      customClues = [];
      $("huntTitle").value = "Tonight’s Backyard Sky Quest";
      $("huntDate").value = todayForInput();
      $("difficulty").value = "mixed";
      $("skyNote").value = "Backyard. Look away from porch lights. Trees block part of the western sky.";
      $("leaderNote").value = "Use red or dim flashlights if you have them. Let your eyes adjust for 10 minutes. Not every clue needs to be visible tonight.";
      $("customItem").value = "";
      renderLibrary();
      buildHunt();
    }

    $("buildBtn").addEventListener("click", buildHunt);
    $("printBtn").addEventListener("click", () => {
      buildHunt();
      window.print();
    });

    $("resetBtn").addEventListener("click", resetHunt);

    $("addCustom").addEventListener("click", () => {
      const value = $("customItem").value.trim();
      if (!value) return;
      customClues.push(value);
      $("customItem").value = "";
      buildHunt();
    });

    ["huntTitle", "huntDate", "skyNote", "leaderNote", "difficulty"].forEach(id => {
      $(id).addEventListener("input", buildHunt);
      $(id).addEventListener("change", buildHunt);
    });

    loadState();
    renderLibrary();
    buildHunt();
  </script>
</body>
</html>

