<body>
  <div class="stars"></div>

  <main class="app">
    <header>
      <div>
        <h1>Backyard Stargazing Scavenger Hunt</h1>
        <p class="subtitle">
          Enter tonight’s details, choose what kids should search for, then print clue cards, a kid checklist, a separate parent answer key, and a copyable text version for another parent.
        </p>
      </div>
      <div class="moon-badge">🌙 Print ready</div>
    </header>

    <section class="layout">
      <aside class="panel controls">
        <div class="panel-inner">
          <div class="panel-title">
            <h2>Hunt setup</h2>
            <span class="chip">One file</span>
          </div>

          <label for="huntTitle">Hunt name</label>
          <input id="huntTitle" value="Tonight’s Backyard Sky Quest" />

          <div class="row">
            <div>
              <label for="huntDate">Date</label>
              <input id="huntDate" type="date" />
            </div>
            <div>
              <label for="difficulty">Kid level</label>
              <select id="difficulty">
                <option value="little">Little explorers</option>
                <option value="mixed" selected>Mixed ages</option>
                <option value="older">Older kids</option>
              </select>
            </div>
          </div>

          <label for="skyNote">Rough location or sky note</label>
          <textarea id="skyNote">Backyard. Look away from porch lights. Trees block part of the western sky.</textarea>

          <label for="leaderNote">Leader note for the printout</label>
          <textarea id="leaderNote">Use red or dim flashlights if you have them. Let your eyes adjust for 10 minutes. Not every clue needs to be visible tonight.</textarea>

          <label>Choose clue cards</label>
          <div class="library" id="library"></div>

          <label for="customItem">Add a custom thing to find</label>
          <div class="custom-add">
            <input id="customItem" placeholder="Example: airplane blinking lights" />
            <button class="small secondary" id="addCustom" type="button">Add</button>
          </div>

          <div class="actions">
            <button id="buildBtn" type="button">Build printable hunt</button>
            <div class="action-row">
              <button class="secondary" id="printKidsBtn" type="button">Print kid cards</button>
              <button class="secondary" id="printAnswerBtn" type="button">Print answer key</button>
            </div>
            <button class="secondary" id="copyBtn" type="button">Copy text export</button>
            <button class="secondary" id="resetBtn" type="button">Reset</button>
            <div class="status" id="copyStatus"></div>
          </div>

          <p class="hint">
            This page does not calculate exact astronomy positions. It gives kid-friendly clues that work with your date and sky note, so you can quickly adapt to clouds, trees, city lights, or whatever is actually visible.
          </p>
        </div>
      </aside>

      <section class="preview">
        <div class="print-toolbar no-print">
          <span>
            Print kid cards for the scavenger hunt. Print the parent key separately so the answers stay off the clue cards.
          </span>
          <div class="action-row">
            <button class="small secondary" id="toolbarPrintKids" type="button">Print kid cards</button>
            <button class="small secondary" id="toolbarPrintAnswer" type="button">Print parent key</button>
          </div>
        </div>

        <div class="print-sheet" id="printSheet">
          <div class="sheet-head">
            <div>
              <h2 id="outTitle">Tonight’s Backyard Sky Quest</h2>
              <div class="sheet-meta">
                <div><strong>Date:</strong> <span id="outDate">Tonight</span></div>
                <div><strong>Sky note:</strong> <span id="outSky">Backyard. Look away from porch lights.</span></div>
              </div>
            </div>
            <div class="night-note">
              <strong>Leader note:</strong>
              <div id="outLeader">Use red or dim flashlights if you have them. Let your eyes adjust for 10 minutes.</div>
            </div>
          </div>

          <div class="cards" id="cards"></div>

          <div class="checklist-wrap">
            <div class="checklist">
              <h3>Finder checklist</h3>
              <div class="check-grid" id="checklist"></div>
              <div class="parent-notes">
                <strong>Bonus challenge:</strong> Pick your favorite find and draw it on the back of a clue card. Add one sentence about where you saw it in the sky.
              </div>
            </div>
          </div>
        </div>

        <div class="answer-sheet" id="answerSheet">
          <div class="sheet-head">
            <div>
              <h2>Parent Answer Key</h2>
              <div class="sheet-meta">
                <div><strong>Hunt:</strong> <span id="keyTitle">Tonight’s Backyard Sky Quest</span></div>
                <div><strong>Date:</strong> <span id="keyDate">Tonight</span></div>
              </div>
            </div>
            <div class="night-note">
              <strong>Use this quietly:</strong>
              <div>These are guide answers, not strict astronomy rules. Visibility depends on clouds, trees, light pollution, time, and direction.</div>
            </div>
          </div>

          <div class="answer-wrap">
            <div class="answer-key">
              <h3>What each clue is trying to find</h3>
              <div class="answers" id="answers"></div>
              <div class="parent-notes">
                <strong>Parent tip:</strong> If a clue is not visible, turn it into an observation question: “Why might this be hard to see tonight?”
              </div>
            </div>
          </div>
        </div>

        <div class="export-sheet no-print">
          <div class="sheet-head">
            <div>
              <h2>Copy or export text version</h2>
              <div class="sheet-meta">
                <div>Use this to text or email another parent.</div>
              </div>
            </div>
            <div class="night-note">
              <strong>Included:</strong>
              <div>Hunt details, kid clue list, checklist, and parent answer key.</div>
            </div>
          </div>

          <div class="export-wrap">
            <div class="export-box">
              <h3>Text export</h3>
              <textarea id="exportText" readonly></textarea>
              <div class="actions">
                <button class="secondary" id="copyBtn2" type="button">Copy text export</button>
              </div>
              <div class="status" id="copyStatus2"></div>
            </div>
          </div>
        </div>
      </section>
    </section>
  </main>

  <script>
    const clueBank = [
      {
