HTML
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Backyard Stargazing Scavenger Hunt</title>
  <style>
    :root {
      --bg: #07111f;
      --panel: #101d31;
      --ink: #f5f7fb;
      --muted: #aebbd1;
      --line: rgba(255,255,255,.14);
      --accent: #ffd166;
      --accent2: #7dd3fc;
      --good: #9ef01a;
      --shadow: 0 20px 60px rgba(0,0,0,.35);
      --radius: 22px;
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      font-family: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at 18% 8%, rgba(125, 211, 252, .18), transparent 28%),
        radial-gradient(circle at 82% 16%, rgba(255, 209, 102, .15), transparent 26%),
        linear-gradient(145deg, #040912, var(--bg) 45%, #0d1b2f);
      color: var(--ink);
      min-height: 100vh;
    }

    .stars {
      position: fixed;
      inset: 0;
      pointer-events: none;
      opacity: .55;
      background-image:
        radial-gradient(circle, rgba(255,255,255,.8) 1px, transparent 1.6px),
        radial-gradient(circle, rgba(255,255,255,.55) 1px, transparent 1.6px),
        radial-gradient(circle, rgba(255,255,255,.35) 1px, transparent 1.6px);
      background-size: 90px 90px, 140px 140px, 210px 210px;
      background-position: 10px 20px, 50px 80px, 120px 20px;
    }

    .app {
      position: relative;
      width: min(1180px, calc(100% - 32px));
      margin: 0 auto;
      padding: 36px 0 56px;
    }

    header {
      display: grid;
      grid-template-columns: 1fr auto;
      gap: 20px;
      align-items: start;
      margin-bottom: 22px;
    }

    h1 {
      margin: 0;
      font-size: clamp(2rem, 5vw, 4.6rem);
      line-height: .95;
      letter-spacing: -0.06em;
    }

    .subtitle {
      margin: 14px 0 0;
      max-width: 840px;
      color: var(--muted);
      font-size: 1.05rem;
      line-height: 1.55;
    }

    .moon-badge {
      border: 1px solid var(--line);
      background: rgba(255,255,255,.06);
      border-radius: 999px;
      padding: 12px 16px;
      color: var(--accent);
      font-weight: 800;
      white-space: nowrap;
      box-shadow: var(--shadow);
    }

    .layout {
      display: grid;
      grid-template-columns: 390px 1fr;
      gap: 20px;
      align-items: start;
    }

    .panel {
      background: linear-gradient(180deg, rgba(255,255,255,.08), rgba(255,255,255,.04));
      border: 1px solid var(--line);
      border-radius: var(--radius);
      box-shadow: var(--shadow);
      overflow: hidden;
      backdrop-filter: blur(12px);
    }

    .panel-inner {
      padding: 20px;
    }

    .panel-title {
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 12px;
      margin-bottom: 16px;
    }

    .panel-title h2 {
      margin: 0;
      font-size: 1.05rem;
      letter-spacing: -0.02em;
    }

    .chip {
      font-size: .78rem;
      font-weight: 800;
      color: #07111f;
      background: var(--accent);
      border-radius: 999px;
      padding: 6px 10px;
    }

    label {
      display: block;
      margin: 14px 0 7px;
      color: var(--muted);
      font-size: .88rem;
      font-weight: 700;
    }

    input,
    textarea,
    select {
      width: 100%;
      border: 1px solid rgba(255,255,255,.16);
      background: rgba(5, 13, 25, .7);
      color: var(--ink);
      border-radius: 14px;
      padding: 12px 13px;
      font: inherit;
      outline: none;
    }

    textarea {
      min-height: 94px;
      resize: vertical;
    }

    #exportText {
      min-height: 260px;
      font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", monospace;
      font-size: .84rem;
      line-height: 1.45;
    }

    input:focus,
    textarea:focus,
    select:focus {
      border-color: rgba(125, 211, 252, .75);
      box-shadow: 0 0 0 4px rgba(125, 211, 252, .13);
    }

    .row {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 12px;
    }

    .actions {
      display: grid;
      gap: 10px;
      margin-top: 18px;
    }

    .action-row {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 10px;
    }

    button {
      border: 0;
      cursor: pointer;
      border-radius: 16px;
      padding: 13px 15px;
      font: inherit;
      font-weight: 900;
      color: #07111f;
      background: var(--accent);
      box-shadow: 0 10px 24px rgba(0,0,0,.24);
    }

    button.secondary {
      background: rgba(255,255,255,.1);
      color: var(--ink);
      border: 1px solid var(--line);
    }

    button.small {
      padding: 9px 10px;
      border-radius: 12px;
      font-size: .86rem;
    }

    button:hover {
      filter: brightness(1.04);
      transform: translateY(-1px);
    }

    .hint {
      color: var(--muted);
      font-size: .85rem;
      line-height: 1.45;
      margin-top: 12px;
    }

    .status {
      color: var(--good);
      font-size: .86rem;
      font-weight: 800;
      min-height: 20px;
      margin-top: 8px;
    }

    .custom-add {
      display: grid;
      grid-template-columns: 1fr auto;
      gap: 8px;
      margin-top: 8px;
    }

    .preview {
      display: grid;
      gap: 20px;
    }

    .print-toolbar {
      display: flex;
      flex-wrap: wrap;
      gap: 10px;
      align-items: center;
      justify-content: space-between;
      padding: 14px;
      border: 1px solid var(--line);
      border-radius: var(--radius);
      background: rgba(255,255,255,.05);
    }

    .print-toolbar span {
      color: var(--muted);
      font-size: .92rem;
      line-height: 1.35;
    }

    .print-sheet,
    .answer-sheet,
    .export-sheet {
      background: rgba(255,255,255,.05);
      border: 1px solid var(--line);
      border-radius: var(--radius);
      overflow: hidden;
    }

    .sheet-head {
      padding: 22px;
      display: grid;
      grid-template-columns: 1fr auto;
      gap: 14px;
      align-items: start;
      border-bottom: 1px solid var(--line);
      background:
        radial-gradient(circle at 10% 20%, rgba(255, 209, 102, .16), transparent 25%),
        linear-gradient(135deg, rgba(255,255,255,.08), rgba(255,255,255,.03));
    }

    .sheet-head h2 {
      margin: 0;
      font-size: clamp(1.4rem, 3vw, 2.1rem);
      letter-spacing: -0.04em;
    }

    .sheet-meta {
      margin-top: 8px;
      color: var(--muted);
      display: grid;
      gap: 4px;
      font-size: .95rem;
    }

    .night-note {
      border: 1px dashed rgba(255,255,255,.25);
      border-radius: 16px;
      padding: 12px;
      color: var(--muted);
      max-width: 370px;
      font-size: .92rem;
      line-height: 1.4;
    }

    .sky-map-wrap {
      padding: 20px 20px 0;
    }

    .sky-map-panel {
      border: 1px solid var(--line);
      border-radius: 22px;
      background:
        radial-gradient(circle at 50% 45%, rgba(125,211,252,.14), transparent 34%),
        linear-gradient(180deg, rgba(255,255,255,.08), rgba(255,255,255,.035));
      padding: 18px;
      page-break-inside: avoid;
      break-inside: avoid;
    }

    .map-title-row {
      display: flex;
      justify-content: space-between;
      gap: 12px;
      align-items: baseline;
      margin-bottom: 14px;
    }

    .map-title-row h3 {
      margin: 0;
      letter-spacing: -0.03em;
    }

    .map-title-row span {
      color: var(--muted);
      font-size: .88rem;
    }

    .sky-map {
      position: relative;
      width: min(100%, 560px);
      aspect-ratio: 1 / 1;
      margin: 0 auto;
      border-radius: 50%;
      border: 2px solid rgba(255,255,255,.28);
      background:
        radial-gradient(circle at 50% 50%, rgba(255,255,255,.10), transparent 10%),
        radial-gradient(circle at 50% 50%, rgba(255,255,255,.05), transparent 31%),
        radial-gradient(circle at 50% 50%, rgba(255,255,255,.03), transparent 52%),
        rgba(2, 8, 19, .55);
      overflow: hidden;
      box-shadow: inset 0 0 35px rgba(0,0,0,.4);
    }

    .sky-map::before,
    .sky-map::after {
      content: "";
      position: absolute;
      background: rgba(255,255,255,.12);
      z-index: 1;
    }

    .sky-map::before {
      left: 50%;
      top: 0;
      width: 1px;
      height: 100%;
    }

    .sky-map::after {
      left: 0;
      top: 50%;
      width: 100%;
      height: 1px;
    }

    .horizon-ring {
      position: absolute;
      inset: 14%;
      border-radius: 50%;
      border: 1px dashed rgba(255,255,255,.22);
      z-index: 1;
    }

    .zenith {
      position: absolute;
      left: 50%;
      top: 50%;
      transform: translate(-50%, -50%);
      width: 76px;
      height: 76px;
      border-radius: 50%;
      border: 1px solid rgba(255,255,255,.22);
      display: grid;
      place-items: center;
      color: var(--muted);
      font-size: .75rem;
      font-weight: 900;
      z-index: 2;
      background: rgba(255,255,255,.04);
    }

    .dir {
      position: absolute;
      z-index: 4;
      font-weight: 1000;
      color: #07111f;
      background: var(--accent);
      border-radius: 999px;
      width: 38px;
      height: 38px;
      display: grid;
      place-items: center;
      box-shadow: 0 8px 16px rgba(0,0,0,.28);
    }

    .dir.n { top: 8px; left: 50%; transform: translateX(-50%); }
    .dir.e { right: 8px; top: 50%; transform: translateY(-50%); }
    .dir.s { bottom: 8px; left: 50%; transform: translateX(-50%); }
    .dir.w { left: 8px; top: 50%; transform: translateY(-50%); }

    .zone-label {
      position: absolute;
      z-index: 3;
      color: rgba(255,255,255,.82);
      font-weight: 900;
      font-size: .78rem;
      letter-spacing: .04em;
      text-transform: uppercase;
    }

    .zone-label.north { top: 17%; left: 50%; transform: translateX(-50%); }
    .zone-label.east { right: 15%; top: 50%; transform: translateY(-50%) rotate(90deg); }
    .zone-label.south { bottom: 17%; left: 50%; transform: translateX(-50%); }
    .zone-label.west { left: 15%; top: 50%; transform: translateY(-50%) rotate(-90deg); }
    .zone-label.overhead { top: 43%; left: 50%; transform: translateX(-50%); }

    .marker {
      position: absolute;
      z-index: 5;
      transform: translate(-50%, -50%);
      display: grid;
      place-items: center;
      width: 30px;
      height: 30px;
      border-radius: 999px;
      color: #07111f;
      background: var(--accent2);
      font-weight: 1000;
      font-size: .86rem;
      border: 2px solid rgba(255,255,255,.75);
      box-shadow: 0 8px 18px rgba(0,0,0,.3);
    }

    .map-legend {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 8px 14px;
      margin-top: 14px;
      color: var(--muted);
      font-size: .88rem;
      line-height: 1.35;
    }

    .legend-item {
      display: grid;
      grid-template-columns: 26px 1fr;
      gap: 8px;
      align-items: start;
    }

    .legend-num {
      display: inline-grid;
      place-items: center;
      width: 22px;
      height: 22px;
      border-radius: 999px;
      background: rgba(125,211,252,.22);
      color: var(--ink);
      font-weight: 900;
      font-size: .78rem;
    }

    .cards {
      padding: 20px;
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 14px;
    }

    .card {
      min-height: 190px;
      border: 1px solid rgba(255,255,255,.16);
      border-radius: 20px;
      padding: 17px;
      background: linear-gradient(180deg, rgba(255,255,255,.09), rgba(255,255,255,.035));
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      page-break-inside: avoid;
      break-inside: avoid;
    }

    .card-top {
      display: flex;
      align-items: start;
      justify-content: space-between;
      gap: 12px;
    }

    .card h3 {
      margin: 0;
      font-size: 1.14rem;
      letter-spacing: -0.03em;
    }

    .emoji {
      width: 44px;
      height: 44px;
      display: grid;
      place-items: center;
      background: rgba(255,255,255,.1);
      border-radius: 14px;
      font-size: 1.55rem;
      flex: 0 0 auto;
    }

    .look-zone {
      display: inline-flex;
      width: fit-content;
      margin-top: 10px;
      padding: 6px 9px;
      border-radius: 999px;
      color: #07111f;
      background: var(--accent2);
      font-size: .78rem;
      font-weight: 1000;
    }

    .clue {
      margin: 12px 0 0;
      color: var(--muted);
      line-height: 1.42;
      font-size: .95rem;
    }

    .find-line {
      margin-top: 14px;
      border-top: 1px solid rgba(255,255,255,.13);
      padding-top: 11px;
      color: var(--accent2);
      font-size: .9rem;
      font-weight: 800;
    }

    .checklist-wrap,
    .answer-wrap,
    .export-wrap {
      padding: 0 20px 20px;
    }

    .checklist,
    .answer-key,
    .export-box {
      background: rgba(255,255,255,.06);
      border: 1px solid var(--line);
      border-radius: 20px;
      padding: 18px;
    }

    .checklist h3,
    .answer-key h3,
    .export-box h3 {
      margin: 0 0 12px;
      letter-spacing: -0.03em;
    }

    .check-grid {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 8px 14px;
    }

    .check-item {
      display: grid;
      grid-template-columns: 24px 1fr;
      gap: 9px;
      align-items: start;
      color: var(--ink);
      line-height: 1.3;
    }

    .check-item small {
      display: block;
      color: var(--muted);
      margin-top: 2px;
      font-size: .78rem;
      font-weight: 800;
    }

    .box {
      width: 20px;
      height: 20px;
      border: 2px solid rgba(255,255,255,.65);
      border-radius: 5px;
      margin-top: 1px;
    }

    .parent-notes {
      margin-top: 14px;
      color: var(--muted);
      font-size: .9rem;
      line-height: 1.45;
    }

    .answers {
      display: grid;
      gap: 12px;
    }

    .answer-item {
      border: 1px solid rgba(255,255,255,.14);
      border-radius: 16px;
      padding: 13px;
      background: rgba(255,255,255,.04);
      page-break-inside: avoid;
      break-inside: avoid;
    }

    .answer-item strong {
      display: block;
      margin-bottom: 6px;
      color: var(--accent);
    }

    .answer-item div {
      color: var(--muted);
      line-height: 1.42;
      font-size: .94rem;
    }

    .answer-zone {
      display: inline-flex;
      margin: 2px 0 8px;
      padding: 5px 8px;
      border-radius: 999px;
      background: rgba(125,211,252,.18);
      color: var(--ink);
      font-size: .78rem;
      font-weight: 900;
    }

    .empty-state {
      color: var(--muted);
      padding: 30px;
      text-align: center;
      line-height: 1.5;
    }

    .library {
      margin-top: 14px;
      display: grid;
      gap: 8px;
    }

    .library-row {
      display: grid;
      grid-template-columns: auto 1fr;
      gap: 9px;
      align-items: start;
      color: var(--muted);
      font-size: .92rem;
      line-height: 1.35;
    }

    .library-row input {
      width: 18px;
      height: 18px;
      margin-top: 1px;
      accent-color: var(--accent);
    }

    @media (max-width: 900px) {
      header {
        grid-template-columns: 1fr;
      }

      .moon-badge {
        width: fit-content;
      }

      .layout {
        grid-template-columns: 1fr;
      }

      .cards {
        grid-template-columns: 1fr;
      }

      .sheet-head {
        grid-template-columns: 1fr;
      }

      .night-note {
        max-width: none;
      }
    }

    @media (max-width: 560px) {
      .app {
        width: min(100% - 20px, 1180px);
        padding-top: 22px;
      }

      .row,
      .check-grid,
      .action-row,
      .map-legend {
        grid-template-columns: 1fr;
      }

      .panel-inner,
      .cards,
      .sheet-head,
      .sky-map-wrap,
      .checklist-wrap,
      .answer-wrap,
      .export-wrap {
        padding: 16px;
      }
    }

    body.print-kids .answer-sheet,
    body.print-kids .export-sheet {
      display: none;
    }

    body.print-answer .print-sheet,
    body.print-answer .export-sheet {
      display: none;
    }

    @media print {
      :root {
        --ink: #111827;
        --muted: #374151;
        --line: #d1d5db;
        --accent: #111827;
        --accent2: #111827;
      }

      body {
        background: #fff;
        color: #111827;
      }

      .stars,
      header,
      .controls,
      .hint,
      .no-print,
      .print-toolbar,
      .export-sheet {
        display: none !important;
      }

      body.print-answer .export-sheet {
        display: none !important;
      }

      .app {
        width: 100%;
        padding: 0;
        margin: 0;
      }

      .layout {
        display: block;
      }

      .preview,
      .print-sheet,
      .answer-sheet {
        display: block;
      }

      .print-sheet,
      .answer-sheet {
        border: 0;
        border-radius: 0;
        background: #fff;
        overflow: visible;
      }

      .answer-sheet {
        page-break-before: always;
      }

      body.print-kids .answer-sheet {
        display: none !important;
      }

      body.print-answer .print-sheet {
        display: none !important;
      }

      body.print-answer .answer-sheet {
        page-break-before: auto;
      }

      .sheet-head {
        background: #fff;
        color: #111827;
        border: 2px solid #111827;
        border-radius: 12px;
        margin-bottom: 14px;
        padding: 16px;
      }

      .sheet-head h2 {
        font-size: 28px;
      }

      .sheet-meta,
      .night-note,
      .clue,
      .parent-notes,
      .answer-item div,
      .map-title-row span,
      .map-legend,
      .check-item small {
        color: #374151;
      }

      .night-note {
        border-color: #9ca3af;
      }

      .sky-map-wrap {
        padding: 0 0 14px;
      }

      .sky-map-panel {
        background: #fff;
        border: 2px solid #111827;
        border-radius: 12px;
        padding: 14px;
      }

      .sky-map {
        width: 460px;
        max-width: 100%;
        background: #fff;
        border-color: #111827;
        box-shadow: none;
      }

      .sky-map::before,
      .sky-map::after {
        background: #d1d5db;
      }

      .horizon-ring {
        border-color: #9ca3af;
      }

      .zenith {
        color: #111827;
        background: #fff;
        border-color: #9ca3af;
      }

      .dir {
        background: #111827;
        color: #fff;
        box-shadow: none;
      }

      .zone-label {
        color: #374151;
      }

      .marker {
        background: #fff;
        color: #111827;
        border: 2px solid #111827;
        box-shadow: none;
      }

      .legend-num {
        background: #fff;
        color: #111827;
        border: 1px solid #111827;
      }

      .cards {
        display: grid;
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
        padding: 0;
      }

      .card {
        background: #fff;
        color: #111827;
        border: 2px solid #111827;
        border-radius: 12px;
        min-height: 160px;
        padding: 13px;
      }

      .emoji {
        background: #f3f4f6;
        border: 1px solid #d1d5db;
      }

      .look-zone {
        background: #fff;
        color: #111827;
        border: 1px solid #111827;
      }

      .find-line {
        border-color: #d1d5db;
        color: #111827;
      }

      .checklist-wrap,
      .answer-wrap {
        padding: 14px 0 0;
      }

      .checklist,
      .answer-key {
        background: #fff;
        border: 2px solid #111827;
        border-radius: 12px;
      }

      .check-grid {
        grid-template-columns: repeat(2, 1fr);
      }

      .box {
        border-color: #111827;
      }

      .answer-item {
        background: #fff;
        border: 1px solid #9ca3af;
      }

      .answer-item strong,
      .answer-zone {
        color: #111827;
      }

      .answer-zone {
        background: #fff;
        border: 1px solid #111827;
      }

      @page {
        margin: .45in;
      }
    }
  </style>
</head>
<body>
  <div class="stars"></div>

  <main class="app">
    <header>
      <div>
        <h1>Backyard Stargazing Scavenger Hunt</h1>
        <p class="subtitle">
          Enter tonight’s details, choose what kids should search for, then print clue cards, a compass sky map, a kid checklist, a separate parent answer key, and a copyable text version for another parent.
        </p>
      </div>
      <div class="moon-badge">🌙 Sky map ready</div>
    </header>

    <section class="layout">
      <aside class="panel controls">
        <div class="panel-inner">
          <div class="panel-title">
            <h2>Hunt setup</h2>
            <span class="chip">One file</span>
          </div>

          <label for="huntTitle">Hunt name</label>
          <input id="huntTitle" value="Tonight’s Backyard Sky Quest" />

          <div class="row">
            <div>
              <label for="huntDate">Date</label>
              <input id="huntDate" type="date" />
            </div>
            <div>
              <label for="difficulty">Kid level</label>
              <select id="difficulty">
                <option value="little">Little explorers</option>
                <option value="mixed" selected>Mixed ages</option>
                <option value="older">Older kids</option>
              </select>
            </div>
          </div>

          <label for="skyNote">Rough location or sky note</label>
          <textarea id="skyNote">Backyard. Look away from porch lights. Trees block part of the western sky.</textarea>

          <label for="leaderNote">Leader note for the printout</label>
          <textarea id="leaderNote">Use red or dim flashlights if you have them. Let your eyes adjust for 10 minutes. Not every clue needs to be visible tonight.</textarea>

          <label>Choose clue cards</label>
          <div class="library" id="library"></div>

          <label for="customItem">Add a custom thing to find</label>
          <div class="custom-add">
            <input id="customItem" placeholder="Example: airplane blinking lights" />
            <button class="small secondary" id="addCustom" type="button">Add</button>
          </div>

          <div class="actions">
            <button id="buildBtn" type="button">Build printable hunt</button>
            <div class="action-row">
              <button class="secondary" id="printKidsBtn" type="button">Print kid hunt</button>
              <button class="secondary" id="printAnswerBtn" type="button">Print answer key</button>
            </div>
            <button class="secondary" id="copyBtn" type="button">Copy text export</button>
            <button class="secondary" id="resetBtn" type="button">Reset</button>
            <div class="status" id="copyStatus"></div>
          </div>

          <p class="hint">
            The sky map is a simple orientation guide, not a live astronomy chart. It suggests where to start looking, while the parent note handles trees, clouds, porch lights, and timing.
          </p>
        </div>
      </aside>

      <section class="preview">
        <div class="print-toolbar no-print">
          <span>
            The kid printout now starts with a compass sky map. The answer key stays separate so the cards do not give away the targets.
          </span>
          <div class="action-row">
            <button class="small secondary" id="toolbarPrintKids" type="button">Print kid hunt</button>
            <button class="small secondary" id="toolbarPrintAnswer" type="button">Print parent key</button>
          </div>
        </div>

        <div class="print-sheet" id="printSheet">
          <div class="sheet-head">
            <div>
              <h2 id="outTitle">Tonight’s Backyard Sky Quest</h2>
              <div class="sheet-meta">
                <div><strong>Date:</strong> <span id="outDate">Tonight</span></div>
                <div><strong>Sky note:</strong> <span id="outSky">Backyard. Look away from porch lights.</span></div>
              </div>
            </div>
            <div class="night-note">
              <strong>Leader note:</strong>
              <div id="outLeader">Use red or dim flashlights if you have them. Let your eyes adjust for 10 minutes.</div>
            </div>
          </div>

          <div class="sky-map-wrap">
            <div class="sky-map-panel">
              <div class="map-title-row">
                <h3>Simple backyard sky map</h3>
                <span>Face each direction and scan from horizon to overhead.</span>
              </div>
              <div class="sky-map" id="skyMap">
                <div class="horizon-ring"></div>
                <div class="zenith">OVERHEAD</div>
                <div class="dir n">N</div>
                <div class="dir e">E</div>
                <div class="dir s">S</div>
                <div class="dir w">W</div>
                <div class="zone-label north">north</div>
                <div class="zone-label east">east</div>
                <div class="zone-label south">south</div>
                <div class="zone-label west">west</div>
              </div>
              <div class="map-legend" id="mapLegend"></div>
              <div class="parent-notes">
                <strong>Map rule:</strong> These zones are search hints, not exact positions. If something is hidden, mark it as “not visible tonight” and keep going.
              </div>
            </div>
          </div>

          <div class="cards" id="cards"></div>

          <div class="checklist-wrap">
            <div class="checklist">
              <h3>Finder checklist</h3>
              <div class="check-grid" id="checklist"></div>
              <div class="parent-notes">
                <strong>Bonus challenge:</strong> Pick your favorite find and draw it on the back of a clue card. Add one sentence about where you saw it in the sky.
              </div>
            </div>
          </div>
        </div>

        <div class="answer-sheet" id="answerSheet">
          <div class="sheet-head">
            <div>
              <h2>Parent Answer Key</h2>
              <div class="sheet-meta">
                <div><strong>Hunt:</strong> <span id="keyTitle">Tonight’s Backyard Sky Quest</span></div>
                <div><strong>Date:</strong> <span id="keyDate">Tonight</span></div>
              </div>
            </div>
            <div class="night-note">
              <strong>Use this quietly:</strong>
              <div>These are guide answers, not strict astronomy rules. Visibility depends on clouds, trees, light pollution, time, and direction.</div>
            </div>
          </div>

          <div class="answer-wrap">
            <div class="answer-key">
              <h3>What each clue is trying to find</h3>
              <div class="answers" id="answers"></div>
              <div class="parent-notes">
                <strong>Parent tip:</strong> If a clue is not visible, turn it into an observation question: “Why might this be hard to see tonight?”
              </div>
            </div>
          </div>
        </div>

        <div class="export-sheet no-print">
          <div class="sheet-head">
            <div>
              <h2>Copy or export text version</h2>
              <div class="sheet-meta">
                <div>Use this to text or email another parent.</div>
              </div>
            </div>
            <div class="night-note">
              <strong>Included:</strong>
              <div>Hunt details, sky map zones, kid clue list, checklist, and parent answer key.</div>
            </div>
          </div>

          <div class="export-wrap">
            <div class="export-box">
              <h3>Text export</h3>
              <textarea id="exportText" readonly></textarea>
              <div class="actions">
                <button class="secondary" id="copyBtn2" type="button">Copy text export</button>
              </div>
              <div class="status" id="copyStatus2"></div>
            </div>
          </div>
        </div>
      </section>
    </section>
  </main>

  <script>
    const clueBank = [
      {
        id: "moon",
        emoji: "🌙",
        title: "The Moon",
        checklist: "Moon",
        zone: "Any open sky",
        mapX: 50,
        mapY: 38,
        clue: {
