      box-shadow: 0 0 0 4px rgba(125, 211, 252, .13);
    }

    .row {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 12px;
    }

    .actions {
      display: grid;
      gap: 10px;
      margin-top: 18px;
    }

    .action-row {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 10px;
    }

    button {
      border: 0;
      cursor: pointer;
      border-radius: 16px;
      padding: 13px 15px;
      font: inherit;
      font-weight: 900;
      color: #07111f;
      background: var(--accent);
      box-shadow: 0 10px 24px rgba(0,0,0,.24);
    }

    button.secondary {
      background: rgba(255,255,255,.1);
      color: var(--ink);
      border: 1px solid var(--line);
    }

    button.small {
      padding: 9px 10px;
      border-radius: 12px;
      font-size: .86rem;
    }

    button:hover {
      filter: brightness(1.04);
      transform: translateY(-1px);
    }

    .hint {
      color: var(--muted);
      font-size: .85rem;
      line-height: 1.45;
      margin-top: 12px;
    }

    .status {
      color: var(--good);
      font-size: .86rem;
      font-weight: 800;
      min-height: 20px;
      margin-top: 8px;
    }

    .custom-add {
      display: grid;
      grid-template-columns: 1fr auto;
      gap: 8px;
      margin-top: 8px;
    }

    .preview {
      display: grid;
      gap: 20px;
    }

    .print-toolbar {
      display: flex;
      flex-wrap: wrap;
      gap: 10px;
      align-items: center;
      justify-content: space-between;
      padding: 14px;
      border: 1px solid var(--line);
      border-radius: var(--radius);
      background: rgba(255,255,255,.05);
    }

    .print-toolbar span {
      color: var(--muted);
      font-size: .92rem;
      line-height: 1.35;
    }

    .print-sheet,
    .answer-sheet,
    .export-sheet {
      background: rgba(255,255,255,.05);
      border: 1px solid var(--line);
      border-radius: var(--radius);
      overflow: hidden;
    }

    .sheet-head {
      padding: 22px;
      display: grid;
      grid-template-columns: 1fr auto;
      gap: 14px;
      align-items: start;
      border-bottom: 1px solid var(--line);
      background:
        radial-gradient(circle at 10% 20%, rgba(255, 209, 102, .16), transparent 25%),
        linear-gradient(135deg, rgba(255,255,255,.08), rgba(255,255,255,.03));
