    .sheet-head h2 {
      margin: 0;
      font-size: clamp(1.4rem, 3vw, 2.1rem);
      letter-spacing: -0.04em;
    }

    .sheet-meta {
      margin-top: 8px;
      color: var(--muted);
      display: grid;
      gap: 4px;
      font-size: .95rem;
    }

    .night-note {
      border: 1px dashed rgba(255,255,255,.25);
      border-radius: 16px;
      padding: 12px;
      color: var(--muted);
      max-width: 370px;
