          older: "Find the Moon if it is up. Sketch its phase and note whether the bright side points east, west, up, or down."
        },
        find: "Draw its shape.",
        answer: "The Moon, if it is above the horizon. Kids should notice its phase, brightness, color, and whether it makes shadows. If it is not up yet or is hidden, that is still a valid observation."
      },
      {
        id: "bright",
        emoji: "✨",
        title: "Brightest Point",
        checklist: "Brightest star or planet",
        zone: "Open sky, east through south",
        mapX: 66,
        mapY: 43,
        clue: {
          little: "Find the brightest tiny light that is not the Moon. Start in the open sky and ask if it twinkles or shines steady.",
          mixed: "Find the brightest point of light. Start with the most open view from east through south. Stars usually twinkle. Planets often shine more steadily.",
          older: "Compare the brightest point with nearby stars. Record whether it twinkles strongly or looks steady."
        },
        find: "Circle twinkle or steady.",
        answer: "Usually the brightest visible star or planet. A steady bright point may be a planet. A twinkling point is more likely a star. Exact identity depends on date, time, and direction."
      },
      {
        id: "dipper",
        emoji: "🥄",
        title: "Big Dipper Shape",
        checklist: "Big Dipper or spoon shape",
        zone: "North sky",
        mapX: 38,
        mapY: 24,
        clue: {
          little: "Face north and look for stars shaped like a giant spoon or wagon. Count how many stars you can see.",
          mixed: "Face north and try to find a spoon shape. It may be high, low, tilted, or partly hidden.",
          older: "Find the Big Dipper if visible. Use the two stars at the outer bowl edge as pointer stars toward north."
        },
        find: "Count the stars in the shape.",
        answer: "The Big Dipper asterism, part of Ursa Major. It looks like a spoon, ladle, or wagon. It is generally found in the northern sky from most northern hemisphere backyards."
      },
      {
        id: "north",
        emoji: "🧭",
        title: "North Star",
        checklist: "North Star",
        zone: "North sky",
        mapX: 50,
        mapY: 18,
        clue: {
          little: "Face north. Find the star that seems like the sky turns around it. A grownup can help point north.",
          mixed: "Use a compass or phone compass to face north. Look for a medium bright star that stays in nearly the same place.",
          older: "Use the Big Dipper pointer stars to estimate Polaris, the North Star, then mark north on your checklist."
        },
        find: "Write which way north is.",
        answer: "Polaris, the North Star. It is not the brightest star, but it is useful because it sits close to true north in the northern hemisphere."
      },
      {
        id: "triangle",
        emoji: "🔺",
        title: "Summer Triangle",
        checklist: "Three bright stars making a triangle",
        zone: "East to overhead",
        mapX: 70,
        mapY: 28,
        clue: {
          little: "Look east and upward. Try to find three bright stars that make a huge triangle.",
          mixed: "Start in the eastern sky and scan upward for three bright stars spread far apart. Together they can make a big summer sky triangle.",
          older: "Find three bright stars forming a large triangle. Estimate which corner is highest above the horizon."
        },
        find: "Draw the triangle.",
        answer: "The Summer Triangle, made from Vega, Deneb, and Altair. It is easiest during summer and early fall evenings in the northern hemisphere, but visibility depends on time and sky view."
      },
      {
        id: "colors",
        emoji: "🎨",
        title: "Star Colors",
        checklist: "Two stars with different colors",
        zone: "Any dark open sky",
        mapX: 44,
        mapY: 58,
        clue: {
          little: "Look anywhere with darker sky. Find one star that looks white or blue and one that looks yellow or orange.",
          mixed: "Scan a dark open patch of sky and compare stars carefully. Some look icy white, some blue white, some yellow, and some orange.",
          older: "Find two stars with different color temperatures. Record the colors without using a phone screen."
        },
        find: "Write two colors.",
        answer: "Stars can appear blue white, white, yellow, orange, or reddish. Color differences are easier to see with bright stars and after eyes adjust to the dark."
      },
      {
        id: "satellite",
        emoji: "🛰️",
        title: "Silent Mover",
        checklist: "Satellite or slow moving light",
        zone: "Overhead sweep",
        mapX: 54,
        mapY: 50,
        clue: {
          little: "Look overhead and wait. Watch for a tiny light moving smoothly across the sky with no blinking.",
          mixed: "Scan overhead and across the open sky. A satellite looks like a steady dot sliding across the sky. It usually does not blink like a plane.",
          older: "Track a steady moving dot. Estimate its path from horizon to horizon and how long you watched it."
        },
        find: "Point where it started.",
        answer: "A satellite. It usually appears as a steady moving point of light with no blinking. It may fade as it moves into Earth’s shadow."
      },
      {
        id: "plane",
        emoji: "✈️",
        title: "Blinking Plane",
        checklist: "Blinking airplane",
        zone: "Horizon to horizon",
        mapX: 76,
        mapY: 66,
        clue: {
          little: "Look around the edges of the sky. Find a light that blinks red, green, or white. That is probably an airplane.",
          mixed: "Scan low and across the sky for a blinking moving light. Compare it with a satellite, which usually looks steady.",
          older: "Watch a blinking aircraft and note its direction. Compare its speed with any steady moving object."
        },
        find: "Write blink colors.",
        answer: "An airplane or helicopter. Blinking lights and colored lights are the big giveaway. This is useful because kids learn not every light in the sky is a star."
      },
      {
        id: "cloud",
        emoji: "☁️",
        title: "Cloud Window",
        checklist: "A clear patch between clouds",
        zone: "Clearest sky zone",
        mapX: 28,
        mapY: 62,
        clue: {
          little: "Look for the clearest part of the sky. Find a hole in the clouds where stars peek through.",
          mixed: "Look for a clear window between clouds. Watch whether it grows, shrinks, or moves.",
          older: "Track a cloud gap for two minutes. Estimate which direction the clouds are drifting."
        },
        find: "Draw the cloud gap.",
        answer: "A clear patch of sky between clouds. This is included so the hunt still works on imperfect nights."
      },
      {
        id: "milky",
        emoji: "🌌",
        title: "Faint Glow Hunt",
        checklist: "Faint glow or crowded star patch",
        zone: "Darkest sky zone",
        mapX: 36,
        mapY: 40,
        clue: {
          little: "Look in the darkest part of the yard. Search for a soft cloudy glow made of many tiny stars.",
          mixed: "Find the darkest sky patch you can. It might show a crowded star area, thin cloud, or sky glow.",
          older: "Search the darkest part of the sky for a faint band or dense star region. Note how light pollution affects it."
        },
        find: "Mark easy or hard.",
        answer: "A faint star rich area, possible Milky Way glow, thin cloud, or general sky glow. In suburbs or cities, the honest answer may be that it is too bright to see."
      },
      {
        id: "shadow",
        emoji: "👤",
        title: "Moon Shadow",
        checklist: "Shadow made by moonlight",
        zone: "Ground check",
        mapX: 18,
        mapY: 82,
        clue: {
          little: "Look down near your feet. If the Moon is bright, stand still and look for your moon shadow.",
          mixed: "Try to make a shadow using only moonlight. This works best when the Moon is bright and high.",
          older: "Test whether the Moon casts a visible shadow. Record what object made the clearest shadow."
        },
        find: "Write yes or no.",
        answer: "A visible shadow caused by moonlight. This usually needs a bright Moon, a darker yard, and a pale surface like concrete, sidewalk, or paper."
      },
      {
        id: "quiet",
        emoji: "👂",
        title: "Night Sound",
        checklist: "One nighttime sound",
        zone: "Anywhere, eyes closed",
        mapX: 82,
        mapY: 82,
        clue: {
          little: "Pause anywhere in the yard. Close your eyes for ten seconds. What night sound can you hear?",
          mixed: "Take a quiet listening break. Find one sound from nature and one sound from people or cars.",
          older: "Listen for 30 seconds and separate sounds into nature, people, traffic, and weather."
        },
        find: "Write one sound.",
        answer: "Any real nighttime sound. Crickets, wind, leaves, dogs, cars, distant voices, airplanes, and insects all count."
      }
    ];

    let selectedIds = ["moon", "bright", "dipper", "north", "triangle", "colors", "satellite", "plane"];
    let customClues = [];

    const $ = (id) => document.getElementById(id);

    function todayForInput() {
      const now = new Date();
      const offset = now.getTimezoneOffset();
      const local = new Date(now.getTime() - offset * 60000);
      return local.toISOString().slice(0, 10);
    }

    function prettyDate(value) {
      if (!value) return "Tonight";
      const date = new Date(value + "T12:00:00");
      return date.toLocaleDateString(undefined, {
        weekday: "long",
        month: "long",
        day: "numeric",
        year: "numeric"
      });
    }

    function escapeHTML(str) {
      return String(str)
        .replaceAll("&", "&amp;")
        .replaceAll("<", "&lt;")
        .replaceAll(">", "&gt;")
        .replaceAll('"', "&quot;")
        .replaceAll("'", "&#039;");
    }

    function getDifficulty() {
      return $("difficulty").value || "mixed";
    }

    function customPosition(index) {
      const positions = [
        { x: 24, y: 32, zone: "Northwest or open sky" },
        { x: 68, y: 34, zone: "East or open sky" },
        { x: 60, y: 70, zone: "South or open sky" },
        { x: 32, y: 72, zone: "West or open sky" },
        { x: 50, y: 50, zone: "Overhead or open sky" }
      ];
      return positions[index % positions.length];
    }

    function allClues() {
      return [
        ...clueBank,
        ...customClues.map((name, index) => {
          const pos = customPosition(index);
          return {
            id: "custom-" + index + "-" + name.toLowerCase().replace(/[^a-z0-9]+/g, ""),
            emoji: "⭐",
            title: name,
            checklist: name,
            zone: pos.zone,
            mapX: pos.x,
            mapY: pos.y,
            clue: {
              little: "Find this special item: " + name + ". Start in the map zone and ask a grownup for a hint if you need one.",
              mixed: "Find this custom sky item: " + name + ". Start in the suggested zone, then record where you saw it.",
              older: "Find this custom target: " + name + ". Start in the suggested zone and note what helped you identify it."
            },
            find: "Write where you found it.",
            answer: "Custom item chosen by the parent: " + name + ". Decide what counts before starting, then accept reasonable kid observations.",
            custom: true
          };
        })
      ];
    }

    function chosenClues() {
      return allClues().filter(item => selectedIds.includes(item.id) || item.custom);
    }

    function renderLibrary() {
      const library = $("library");
      library.innerHTML = "";

      clueBank.forEach(item => {
        const row = document.createElement("label");
        row.className = "library-row";
        row.innerHTML = `
          <input type="checkbox" value="${item.id}" ${selectedIds.includes(item.id) ? "checked" : ""}>
          <span><strong>${item.emoji} ${escapeHTML(item.title)}</strong><br>${escapeHTML(item.zone)} · ${escapeHTML(item.checklist)}</span>
        `;
        library.appendChild(row);
      });

      library.querySelectorAll("input[type='checkbox']").forEach(box => {
        box.addEventListener("change", () => {
          selectedIds = Array.from(library.querySelectorAll("input[type='checkbox']:checked")).map(input => input.value);
          saveState();
          buildHunt();
        });
      });
    }

    function buildExportText(chosen, title, date, sky, leader, difficulty) {
      const difficultyLabel = {
        little: "Little explorers",
        mixed: "Mixed ages",
        older: "Older kids"
      }[difficulty] || "Mixed ages";

      let text = "";
      text += title + "\n";
      text += "Date: " + date + "\n";
      text += "Kid level: " + difficultyLabel + "\n";
      text += "Sky note: " + sky + "\n";
      text += "Leader note: " + leader + "\n\n";

      text += "ADULT SETUP CHECKLIST\n";
      text += "=====================\n";
      setupItems.forEach(item => {
        text += "[ ] " + item + "\n";
      });
      text += "\nCloud plan: If clouds roll in, switch to moving lights, cloud windows, moon shadows, night sounds, and why-can't-we-see-it observations.\n\n";

      text += "SIMPLE SKY MAP GUIDE\n";
      text += "====================\n";
      text += "Use north, east, south, and west as starting zones. These are search hints, not exact calculated positions.\n";
      text += "Scan from the horizon up toward overhead. If a target is hidden by clouds, trees, houses, or timing, mark it not visible tonight.\n\n";

      chosen.forEach((item, idx) => {
        text += (idx + 1) + ". " + item.title + " · Look zone: " + item.zone + "\n";
      });

      text += "\nKID CLUE CARDS\n";
      text += "==============\n";
      chosen.forEach((item, idx) => {
        text += (idx + 1) + ". " + item.emoji + " " + item.title + "\n";
        text += "Look zone: " + item.zone + "\n";
        text += "Clue: " + (item.clue[difficulty] || item.clue.mixed) + "\n";
        text += "Task: " + item.find + "\n\n";
      });

      text += "FINDER CHECKLIST\n";
      text += "================\n";
      chosen.forEach(item => {
        text += "[ ] " + item.checklist + " · " + item.zone + "\n";
      });

      text += "\nPARENT ANSWER KEY\n";
      text += "=================\n";
      text += "These are guide answers, not strict astronomy rules. Visibility depends on clouds, trees, light pollution, time, and direction.\n\n";
      chosen.forEach((item, idx) => {
        text += (idx + 1) + ". " + item.title + "\n";
        text += "Look zone: " + item.zone + "\n";
        text += "Answer: " + item.answer + "\n\n";
      });

      text += "Parent tip: If a clue is not visible, turn it into an observation question: Why might this be hard to see tonight?\n";

      return text;
    }

    function clearMapMarkers() {
      $("skyMap").querySelectorAll(".marker").forEach(marker => marker.remove());
      $("mapLegend").innerHTML = "";
    }

    function renderSkyMap(chosen) {
      clearMapMarkers();

      chosen.forEach((item, idx) => {
        const marker = document.createElement("div");
        marker.className = "marker";
        marker.style.left = item.mapX + "%";
        marker.style.top = item.mapY + "%";
        marker.textContent = idx + 1;
        marker.title = item.title + " · " + item.zone;
        $("skyMap").appendChild(marker);

        const legend = document.createElement("div");
        legend.className = "legend-item";
        legend.innerHTML = `
          <span class="legend-num">${idx + 1}</span>
          <span><strong>${escapeHTML(item.title)}</strong><br>${escapeHTML(item.zone)}</span>
        `;
        $("mapLegend").appendChild(legend);
      });
    }

    function renderSetupChecklist() {
      const setup = $("setupChecklist");
      setup.innerHTML = "";

      setupItems.forEach(item => {
        const row = document.createElement("div");
        row.className = "check-item";
        row.innerHTML = `
          <span class="box"></span>
          <span>${escapeHTML(item)}</span>
        `;
        setup.appendChild(row);
      });
    }

    function buildHunt() {
      const difficulty = getDifficulty();
      const title = $("huntTitle").value.trim() || "Tonight’s Backyard Sky Quest";
      const date = prettyDate($("huntDate").value);
      const sky = $("skyNote").value.trim() || "Backyard sky check.";
      const leader = $("leaderNote").value.trim() || "Let your eyes adjust and only search for what is visible tonight.";

      $("outTitle").textContent = title;
      $("outDate").textContent = date;
      $("outSky").textContent = sky;
      $("outLeader").textContent = leader;
      $("keyTitle").textContent = title;
      $("keyDate").textContent = date;

      const chosen = chosenClues();
      const cards = $("cards");
      const checklist = $("checklist");
      const answers = $("answers");

      cards.innerHTML = "";
      checklist.innerHTML = "";
      answers.innerHTML = "";

      renderSetupChecklist();

      if (!chosen.length) {
        clearMapMarkers();
        cards.innerHTML = `<div class="empty-state">Pick at least one clue card to build the hunt.</div>`;
        $("exportText").value = "";
        return;
      }

      renderSkyMap(chosen);

      chosen.forEach((item, idx) => {
        const card = document.createElement("article");
        card.className = "card";
        card.innerHTML = `
          <div>
            <div class="card-top">
              <h3>${idx + 1}. ${escapeHTML(item.title)}</h3>
              <div class="emoji">${item.emoji}</div>
            </div>
            <div class="look-zone">Look zone: ${escapeHTML(item.zone)}</div>
            <p class="clue">${escapeHTML(item.clue[difficulty] || item.clue.mixed)}</p>
          </div>
          <div class="find-line">${escapeHTML(item.find)}</div>
        `;
        cards.appendChild(card);

        const check = document.createElement("div");
        check.className = "check-item";
        check.innerHTML = `
          <span class="box"></span>
          <span>${escapeHTML(item.checklist)}<small>${escapeHTML(item.zone)}</small></span>
        `;
        checklist.appendChild(check);

        const answer = document.createElement("div");
        answer.className = "answer-item";
        answer.innerHTML = `
          <strong>${idx + 1}. ${escapeHTML(item.title)}</strong>
          <span class="answer-zone">Look zone: ${escapeHTML(item.zone)}</span>
          <div>${escapeHTML(item.answer)}</div>
        `;
        answers.appendChild(answer);
      });

      $("exportText").value = buildExportText(chosen, title, date, sky, leader, difficulty);

      saveState();
    }

    function saveState() {
      const state = {
        huntTitle: $("huntTitle").value,
        huntDate: $("huntDate").value,
        skyNote: $("skyNote").value,
        leaderNote: $("leaderNote").value,
        difficulty: $("difficulty").value,
        selectedIds,
        customClues
      };
      localStorage.setItem("stargazing-hunt-state", JSON.stringify(state));
    }

    function loadState() {
      const raw = localStorage.getItem("stargazing-hunt-state");
      if (!raw) {
        $("huntDate").value = todayForInput();
        return;
      }

      try {
        const state = JSON.parse(raw);
        $("huntTitle").value = state.huntTitle || "Tonight’s Backyard Sky Quest";
        $("huntDate").value = state.huntDate || todayForInput();
        $("skyNote").value = state.skyNote || "";
        $("leaderNote").value = state.leaderNote || "";
        $("difficulty").value = state.difficulty || "mixed";
        selectedIds = Array.isArray(state.selectedIds) ? state.selectedIds : selectedIds;
        customClues = Array.isArray(state.customClues) ? state.customClues : [];
      } catch {
        $("huntDate").value = todayForInput();
      }
    }

    function resetHunt() {
      localStorage.removeItem("stargazing-hunt-state");
      selectedIds = ["moon", "bright", "dipper", "north", "triangle", "colors", "satellite", "plane"];
      customClues = [];
      $("huntTitle").value = "Tonight’s Backyard Sky Quest";
      $("huntDate").value = todayForInput();
      $("difficulty").value = "mixed";
      $("skyNote").value = "Backyard. Look away from porch lights. Trees block part of the western sky.";
      $("leaderNote").value = "Use red or dim flashlights if you have them. Let your eyes adjust for 10 minutes. Not every clue needs to be visible tonight.";
      $("customItem").value = "";
      $("copyStatus").textContent = "";
      $("copyStatus2").textContent = "";
      renderLibrary();
      buildHunt();
    }

    function loadSampleNight() {
      selectedIds = ["moon", "bright", "dipper", "north", "triangle", "colors", "satellite", "plane", "cloud", "quiet"];
      customClues = ["porch light glow", "favorite constellation shape"];

      $("huntTitle").value = "Sample Backyard Star Quest";
      $("huntDate").value = todayForInput();
      $("difficulty").value = "mixed";
      $("skyNote").value = "Sample backyard night. Face away from porch lights. North is near the back fence. Trees block part of the west. The clearest view is east and overhead.";
      $("leaderNote").value = "Start with 10 quiet seconds, then scan one direction at a time. If clouds roll in, switch to cloud windows, moving lights, moon shadows, and night sounds.";

      renderLibrary();
      buildHunt();
      $("copyStatus").textContent = "Sample night loaded.";
      setTimeout(() => {
        $("copyStatus").textContent = "";
      }, 2200);
    }

    function printMode(mode) {
      buildHunt();
      document.body.classList.remove("print-kids", "print-answer");
      document.body.classList.add(mode);
      window.print();
      setTimeout(() => {
        document.body.classList.remove("print-kids", "print-answer");
      }, 500);
    }

    async function copyExportText(statusId) {
      buildHunt();
      const text = $("exportText").value;
      const status = $(statusId);

      try {
        await navigator.clipboard.writeText(text);
        status.textContent = "Copied.";
      } catch {
        $("exportText").focus();
        $("exportText").select();
        const ok = document.execCommand("copy");
        status.textContent = ok ? "Copied." : "Select the text box and copy manually.";
      }

      setTimeout(() => {
        status.textContent = "";
      }, 2200);
    }

    $("sampleBtn").addEventListener("click", loadSampleNight);
    $("buildBtn").addEventListener("click", buildHunt);
    $("printKidsBtn").addEventListener("click", () => printMode("print-kids"));
    $("printAnswerBtn").addEventListener("click", () => printMode("print-answer"));
    $("toolbarPrintKids").addEventListener("click", () => printMode("print-kids"));
    $("toolbarPrintAnswer").addEventListener("click", () => printMode("print-answer"));
    $("copyBtn").addEventListener("click", () => copyExportText("copyStatus"));
    $("copyBtn2").addEventListener("click", () => copyExportText("copyStatus2"));
    $("resetBtn").addEventListener("click", resetHunt);

    $("addCustom").addEventListener("click", () => {
      const value = $("customItem").value.trim();
      if (!value) return;
      customClues.push(value);
      $("customItem").value = "";
      buildHunt();
    });

    $("customItem").addEventListener("keydown", (event) => {
      if (event.key === "Enter") {
        event.preventDefault();
        $("addCustom").click();
      }
    });

    ["huntTitle", "huntDate", "skyNote", "leaderNote", "difficulty"].forEach(id => {
      $(id).addEventListener("input", buildHunt);
      $(id).addEventListener("change", buildHunt);
    });

    loadState();
    renderLibrary();
    buildHunt();
  </script>
</body>
</html>

