Here is the complete updated HTML. The main changes are tighter mobile spacing, larger tap targets, a cleaner clue-library layout on small screens, and print styling kept clean.

HTML
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Backyard Stargazing Scavenger Hunt</title>
  <style>
    :root {
      --bg: #07111f;
      --ink: #f5f7fb;
      --muted: #aebbd1;
      --line: rgba(255,255,255,.14);
      --accent: #ffd166;
      --accent2: #7dd3fc;
      --good: #9ef01a;
      --shadow: 0 20px 60px rgba(0,0,0,.35);
      --radius: 22px;
      --tap: 48px;
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      font-family: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at 18% 8%, rgba(125, 211, 252, .18), transparent 28%),
        radial-gradient(circle at 82% 16%, rgba(255, 209, 102, .15), transparent 26%),
        linear-gradient(145deg, #040912, var(--bg) 45%, #0d1b2f);
      color: var(--ink);
      min-height: 100vh;
    }

    .stars {
      position: fixed;
      inset: 0;
      pointer-events: none;
      opacity: .55;
      background-image:
        radial-gradient(circle, rgba(255,255,255,.8) 1px, transparent 1.6px),
        radial-gradient(circle, rgba(255,255,255,.55) 1px, transparent 1.6px),
        radial-gradient(circle, rgba(255,255,255,.35) 1px, transparent 1.6px);
      background-size: 90px 90px, 140px 140px, 210px 210px;
      background-position: 10px 20px, 50px 80px, 120px 20px;
    }

    .app {
      position: relative;
      width: min(1180px, calc(100% - 32px));
      margin: 0 auto;
      padding: 36px 0 56px;
    }

    header {
      display: grid;
      grid-template-columns: 1fr auto;
      gap: 20px;
      align-items: start;
      margin-bottom: 22px;
    }

    h1 {
      margin: 0;
      font-size: clamp(2rem, 5vw, 4.6rem);
      line-height: .95;
      letter-spacing: -0.06em;
    }

    .subtitle {
      margin: 14px 0 0;
      max-width: 860px;
      color: var(--muted);
      font-size: 1.05rem;
      line-height: 1.55;
    }

    .moon-badge {
      border: 1px solid var(--line);
      background: rgba(255,255,255,.06);
      border-radius: 999px;
      padding: 12px 16px;
      color: var(--accent);
      font-weight: 800;
      white-space: nowrap;
      box-shadow: var(--shadow);
    }

    .layout {
      display: grid;
      grid-template-columns: 390px 1fr;
      gap: 20px;
      align-items: start;
    }

    .panel {
      background: linear-gradient(180deg, rgba(255,255,255,.08), rgba(255,255,255,.04));
      border: 1px solid var(--line);
      border-radius: var(--radius);
      box-shadow: var(--shadow);
      overflow: hidden;
      backdrop-filter: blur(12px);
    }

    .panel-inner {
      padding: 20px;
    }

    .panel-title {
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 12px;
      margin-bottom: 16px;
    }

    .panel-title h2 {
      margin: 0;
      font-size: 1.05rem;
      letter-spacing: -0.02em;
    }

    .chip {
      font-size: .78rem;
      font-weight: 800;
      color: #07111f;
      background: var(--accent);
      border-radius: 999px;
      padding: 6px 10px;
    }

    label {
      display: block;
      margin: 14px 0 7px;
      color: var(--muted);
      font-size: .88rem;
      font-weight: 700;
    }

    input,
    textarea,
    select {
      width: 100%;
      border: 1px solid rgba(255,255,255,.16);
      background: rgba(5, 13, 25, .7);
      color: var(--ink);
      border-radius: 14px;
      padding: 12px 13px;
      font: inherit;
      outline: none;
    }

    input,
    select {
      min-height: var(--tap);
    }

    textarea {
      min-height: 94px;
      resize: vertical;
    }

    #exportText {
      min-height: 285px;
      font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", monospace;
      font-size: .84rem;
      line-height: 1.45;
    }

    input:focus,
    textarea:focus,
    select:focus {
      border-color: rgba(125, 211, 252, .75);
      box-shadow: 0 0 0 4px rgba(125, 211, 252, .13);
    }

    .row {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 12px;
    }

    .actions {
      display: grid;
      gap: 10px;
      margin-top: 18px;
    }

    .action-row {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 10px;
    }

    button {
      border: 0;
      cursor: pointer;
      border-radius: 16px;
      min-height: var(--tap);
      padding: 13px 15px;
      font: inherit;
      font-weight: 900;
      color: #07111f;
      background: var(--accent);
      box-shadow: 0 10px 24px rgba(0,0,0,.24);
      touch-action: manipulation;
    }

    button.secondary {
      background: rgba(255,255,255,.1);
      color: var(--ink);
      border: 1px solid var(--line);
    }

    button.small {
      min-height: 44px;
      padding: 9px 10px;
      border-radius: 12px;
      font-size: .86rem;
    }

    button:hover {
      filter: brightness(1.04);
      transform: translateY(-1px);
    }

    .hint {
      color: var(--muted);
      font-size: .85rem;
      line-height: 1.45;
      margin-top: 12px;
    }

    .status {
      color: var(--good);
      font-size: .86rem;
      font-weight: 800;
      min-height: 20px;
      margin-top: 8px;
    }

    .custom-add {
      display: grid;
      grid-template-columns: 1fr auto;
      gap: 8px;
      margin-top: 8px;
    }

    .preview {
      display: grid;
      gap: 20px;
    }

    .print-toolbar {
      display: flex;
      flex-wrap: wrap;
      gap: 10px;
      align-items: center;
      justify-content: space-between;
      padding: 14px;
      border: 1px solid var(--line);
      border-radius: var(--radius);
      background: rgba(255,255,255,.05);
    }

    .print-toolbar span {
      color: var(--muted);
      font-size: .92rem;
      line-height: 1.35;
    }

    .print-sheet,
    .answer-sheet,
    .export-sheet {
      background: rgba(255,255,255,.05);
      border: 1px solid var(--line);
      border-radius: var(--radius);
      overflow: hidden;
    }

    .sheet-head {
      padding: 22px;
      display: grid;
      grid-template-columns: 1fr auto;
      gap: 14px;
      align-items: start;
      border-bottom: 1px solid var(--line);
      background:
        radial-gradient(circle at 10% 20%, rgba(255, 209, 102, .16), transparent 25%),
        linear-gradient(135deg, rgba(255,255,255,.08), rgba(255,255,255,.03));
    }

    .sheet-head h2 {
      margin: 0;
      font-size: clamp(1.4rem, 3vw, 2.1rem);
      letter-spacing: -0.04em;
    }

    .sheet-meta {
      margin-top: 8px;
      color: var(--muted);
      display: grid;
      gap: 4px;
      font-size: .95rem;
    }

    .night-note {
      border: 1px dashed rgba(255,255,255,.25);
      border-radius: 16px;
      padding: 12px;
      color: var(--muted);
      max-width: 370px;
      font-size: .92rem;
      line-height: 1.4;
    }

    .sky-map-wrap {
      padding: 20px 20px 0;
    }

    .sky-map-panel {
      border: 1px solid var(--line);
      border-radius: 22px;
      background:
        radial-gradient(circle at 50% 45%, rgba(125,211,252,.14), transparent 34%),
        linear-gradient(180deg, rgba(255,255,255,.08), rgba(255,255,255,.035));
      padding: 18px;
      page-break-inside: avoid;
      break-inside: avoid;
    }

    .map-title-row {
      display: flex;
      justify-content: space-between;
      gap: 12px;
      align-items: baseline;
      margin-bottom: 14px;
    }

    .map-title-row h3 {
      margin: 0;
      letter-spacing: -0.03em;
    }

    .map-title-row span {
      color: var(--muted);
      font-size: .88rem;
    }

    .sky-map {
      position: relative;
      width: min(100%, 560px);
      aspect-ratio: 1 / 1;
      margin: 0 auto;
      border-radius: 50%;
      border: 2px solid rgba(255,255,255,.28);
      background:
        radial-gradient(circle at 50% 50%, rgba(255,255,255,.10), transparent 10%),
        radial-gradient(circle at 50% 50%, rgba(255,255,255,.05), transparent 31%),
        radial-gradient(circle at 50% 50%, rgba(255,255,255,.03), transparent 52%),
        rgba(2, 8, 19, .55);
      overflow: hidden;
      box-shadow: inset 0 0 35px rgba(0,0,0,.4);
    }

    .sky-map::before,
    .sky-map::after {
      content: "";
      position: absolute;
      background: rgba(255,255,255,.12);
      z-index: 1;
    }

    .sky-map::before {
      left: 50%;
      top: 0;
      width: 1px;
      height: 100%;
    }

    .sky-map::after {
      left: 0;
      top: 50%;
      width: 100%;
      height: 1px;
    }

    .horizon-ring {
      position: absolute;
      inset: 14%;
      border-radius: 50%;
      border: 1px dashed rgba(255,255,255,.22);
      z-index: 1;
    }

    .zenith {
      position: absolute;
      left: 50%;
      top: 50%;
      transform: translate(-50%, -50%);
      width: 76px;
      height: 76px;
      border-radius: 50%;
      border: 1px solid rgba(255,255,255,.22);
      display: grid;
      place-items: center;
      color: var(--muted);
      font-size: .75rem;
      font-weight: 900;
      z-index: 2;
      background: rgba(255,255,255,.04);
    }

    .dir {
      position: absolute;
      z-index: 4;
      font-weight: 1000;
      color: #07111f;
      background: var(--accent);
      border-radius: 999px;
      width: 38px;
      height: 38px;
      display: grid;
      place-items: center;
      box-shadow: 0 8px 16px rgba(0,0,0,.28);
    }

    .dir.n { top: 8px; left: 50%; transform: translateX(-50%); }
    .dir.e { right: 8px; top: 50%; transform: translateY(-50%); }
    .dir.s { bottom: 8px; left: 50%; transform: translateX(-50%); }
    .dir.w { left: 8px; top: 50%; transform: translateY(-50%); }

    .zone-label {
      position: absolute;
      z-index: 3;
      color: rgba(255,255,255,.82);
      font-weight: 900;
      font-size: .78rem;
      letter-spacing: .04em;
      text-transform: uppercase;
    }

    .zone-label.north { top: 17%; left: 50%; transform: translateX(-50%); }
    .zone-label.east { right: 15%; top: 50%; transform: translateY(-50%) rotate(90deg); }
    .zone-label.south { bottom: 17%; left: 50%; transform: translateX(-50%); }
    .zone-label.west { left: 15%; top: 50%; transform: translateY(-50%) rotate(-90deg); }

    .marker {
      position: absolute;
      z-index: 5;
      transform: translate(-50%, -50%);
      display: grid;
      place-items: center;
      width: 30px;
      height: 30px;
      border-radius: 999px;
      color: #07111f;
      background: var(--accent2);
      font-weight: 1000;
      font-size: .86rem;
      border: 2px solid rgba(255,255,255,.75);
      box-shadow: 0 8px 18px rgba(0,0,0,.3);
    }

    .map-legend {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 8px 14px;
      margin-top: 14px;
      color: var(--muted);
      font-size: .88rem;
      line-height: 1.35;
    }

    .legend-item {
      display: grid;
      grid-template-columns: 26px 1fr;
      gap: 8px;
      align-items: start;
      min-width: 0;
    }

    .legend-item span:last-child {
      min-width: 0;
      overflow-wrap: anywhere;
    }

    .legend-num {
      display: inline-grid;
      place-items: center;
      width: 22px;
      height: 22px;
      border-radius: 999px;
      background: rgba(125,211,252,.22);
      color: var(--ink);
      font-weight: 900;
      font-size: .78rem;
    }

    .cards {
      padding: 20px;
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 14px;
    }

    .card {
      min-height: 190px;
      border: 1px solid rgba(255,255,255,.16);
      border-radius: 20px;
      padding: 17px;
      background: linear-gradient(180deg, rgba(255,255,255,.09), rgba(255,255,255,.035));
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      page-break-inside: avoid;
      break-inside: avoid;
    }

    .card-top {
      display: flex;
      align-items: start;
      justify-content: space-between;
      gap: 12px;
    }

    .card h3 {
      margin: 0;
      font-size: 1.14rem;
      letter-spacing: -0.03em;
    }

    .emoji {
      width: 44px;
      height: 44px;
      display: grid;
      place-items: center;
      background: rgba(255,255,255,.1);
      border-radius: 14px;
      font-size: 1.55rem;
      flex: 0 0 auto;
    }

    .look-zone {
      display: inline-flex;
      width: fit-content;
      margin-top: 10px;
      padding: 6px 9px;
      border-radius: 999px;
      color: #07111f;
      background: var(--accent2);
      font-size: .78rem;
      font-weight: 1000;
    }

    .clue {
      margin: 12px 0 0;
