      font-size: .95rem;
    }

    .find-line {
      margin-top: 14px;
      border-top: 1px solid rgba(255,255,255,.13);
      padding-top: 11px;
      color: var(--accent2);
      font-size: .9rem;
      font-weight: 800;
    }

    .checklist-wrap,
    .answer-wrap,
    .export-wrap {
      padding: 0 20px 20px;
    }

    .checklist,
    .answer-key,
    .export-box,
    .setup-key {
      background: rgba(255,255,255,.06);
      border: 1px solid var(--line);
      border-radius: 20px;
      padding: 18px;
    }

    .checklist h3,
    .answer-key h3,
    .export-box h3,
    .setup-key h3 {
      margin: 0 0 12px;
      letter-spacing: -0.03em;
    }

    .check-grid,
    .setup-grid {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 8px 14px;
    }

    .check-item {
      display: grid;
      grid-template-columns: 24px 1fr;
      gap: 9px;
      align-items: start;
      color: var(--ink);
      line-height: 1.3;
      min-width: 0;
    }

    .check-item span:last-child {
      min-width: 0;
      overflow-wrap: anywhere;
    }

    .check-item small {
      display: block;
      color: var(--muted);
      margin-top: 2px;
      font-size: .78rem;
      font-weight: 800;
    }

    .box {
      width: 20px;
      height: 20px;
      border: 2px solid rgba(255,255,255,.65);
      border-radius: 5px;
      margin-top: 1px;
      flex: 0 0 auto;
    }

    .parent-notes {
      margin-top: 14px;
      color: var(--muted);
