      line-height: 1.45;
    }

    .answers {
      display: grid;
      gap: 12px;
    }

    .answer-item {
      border: 1px solid rgba(255,255,255,.14);
      border-radius: 16px;
      padding: 13px;
      background: rgba(255,255,255,.04);
      page-break-inside: avoid;
      break-inside: avoid;
    }

    .answer-item strong {
      display: block;
      margin-bottom: 6px;
      color: var(--accent);
    }

    .answer-item div {
      color: var(--muted);
