      font-size: .94rem;
    }

    .answer-zone {
      display: inline-flex;
      margin: 2px 0 8px;
      padding: 5px 8px;
      border-radius: 999px;
      background: rgba(125,211,252,.18);
      color: var(--ink);
      font-size: .78rem;
      font-weight: 900;
    }

    .empty-state {
      color: var(--muted);
      padding: 30px;
      text-align: center;
      line-height: 1.5;
    }

    .library {
      margin-top: 14px;
      display: grid;
      gap: 8px;
    }

    .library-row {
      display: grid;
      grid-template-columns: 28px minmax(0, 1fr);
      gap: 10px;
      align-items: start;
      color: var(--muted);
      font-size: .92rem;
      line-height: 1.35;
      border: 1px solid rgba(255,255,255,.08);
      border-radius: 14px;
      padding: 10px;
      background: rgba(255,255,255,.035);
      cursor: pointer;
    }

    .library-row strong {
      color: var(--ink);
    }

    .library-row .library-copy {
      min-width: 0;
      overflow-wrap: anywhere;
    }

    .library-row input {
      width: 20px;
      height: 20px;
      margin: 2px 0 0;
      accent-color: var(--accent);
    }

    @media (max-width: 900px) {
      header {
        grid-template-columns: 1fr;
      }

